#!/usr/bin/env node
// Regenerates lib/autobuild-script-body.ts from scripts/autobuild/aib-autobuild.sh.
// Usage: node scripts/aib-gen-autobuild.mjs [--check]
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(fileURLToPath(new URL("..", import.meta.url)));
const source = path.join(root, "scripts/autobuild/aib-autobuild.sh");
const target = path.join(root, "lib/autobuild-script-body.ts");
const body = fs.readFileSync(source, "utf8");
const output =
  "// GENERATED by scripts/aib-gen-autobuild.mjs from scripts/autobuild/aib-autobuild.sh — do not edit by hand.\n" +
  "// Run `node scripts/aib-gen-autobuild.mjs` after changing the shell source.\n" +
  `export const AUTOBUILD_SCRIPT_BODY: string = ${JSON.stringify(body)};\n`;
if (process.argv.includes("--check")) {
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (current !== output) {
    console.error("AUTOBUILD_BODY_OUT_OF_SYNC: run node scripts/aib-gen-autobuild.mjs");
    process.exit(1);
  }
  console.log("AUTOBUILD_BODY_IN_SYNC bytes=" + Buffer.byteLength(body));
} else {
  fs.writeFileSync(target, output);
  console.log("AUTOBUILD_BODY_WRITTEN bytes=" + Buffer.byteLength(body));
}
